// Normalize the Gmail message.
const m = $json;
const from = m.from?.value?.[0]?.address ?? m.from?.text ?? m.From ?? '';
const body = String(m.text ?? m.textPlain ?? m.snippet ?? '').replace(/\n{3,}/g, '\n\n').trim();
return [{ json: { messageId: m.id, threadId: m.threadId, from, subject: m.subject ?? m.Subject ?? '', body } }];

const schema = {
  type: 'object', additionalProperties: false,
  properties: {
    category: { type: 'string', enum: ['billing', 'technical', 'account', 'sales', 'complaint', 'other'] },
    priority: { type: 'string', enum: ['low', 'normal', 'high', 'urgent'] },
    sentiment: { type: 'string', enum: ['positive', 'neutral', 'negative'] },
    language: { type: 'string' },
    needs_human: { type: 'boolean' },
    reason: { type: 'string' },
    draft_reply: { type: 'string' },
  },
  required: ['category', 'priority', 'sentiment', 'language', 'needs_human', 'reason', 'draft_reply'],
};

return [{ json: {
  ...$json,
  openai_payload: {
    model: $env.OPENAI_MODEL || 'gpt-5.6-luna',
    instructions: 'You are a customer support assistant. Classify the email and write a DRAFT reply that a human agent will review ' + 'before sending. Reply in the customer language, be warm and concrete, and ask for any missing details. ' + 'Never promise refunds, discounts, deadlines or anything you cannot verify; if the request needs a decision ' + '(refund, legal, complaint, cancellation) set needs_human=true and write a short holding reply.' + ($env.SUPPORT_CONTEXT ? '\n\nCompany context:\n' + $env.SUPPORT_CONTEXT : ''),
    input: `From: ${$json.from}\nSubject: ${$json.subject}\n\n${String($json.body).slice(0, 8000)}`,
    text: { format: { type: 'json_schema', name: 'support_triage', strict: true, schema } },
  },
} }];

function parseResponse(res) {
  const message = (res.output || []).find(o => o.type === 'message');
  const part = message?.content?.find(c => c.type === 'output_text' || c.type === 'refusal');
  if (!part || part.type === 'refusal') throw new Error('The model returned no usable answer: ' + JSON.stringify(res).slice(0, 300));
  return JSON.parse(part.text);
}

const src = $('Normalize email').item.json;
const t = parseResponse($json);
return [{ json: {
  ...src, ...t,
  reply_subject: /^re:/i.test(src.subject) ? src.subject : `Re: ${src.subject}`,
  logged_at: new Date().toISOString(),
  thread_url: `https://mail.google.com/mail/u/0/#all/${src.threadId}`,
} }];
